fn gcd(a: Int, b: Int) -> Int {
    if b == 0 {
        a
    } else {
        gcd(b, a % b)
    }
}
fn main() {
    print(gcd(252, 105))
}

fn is_prime(n: Int) -> Bool {
    if n <= 1 {
        return false
    }
    for i in range(2, n) {
        if n % i == 0 {
            return false
        }
    }
    true
}
fn main() {
    let mut count = 0
    for i in range(2, 100) {
        if is_prime(i) {
            count = count + 1
        }
    }
    print(count)
}

fn fib(n: Int) -> Int {
    if n <= 2 {
        1
    } else {
        fib(n - 1) + fib(n - 2)
    }
}
